WITH filtered AS (SELECT id, product_id, quantity, last_restock, DATEDIFF(CURRENT_DATE(), last_restock) AS days_since_last_restock FROM inventory WHERE store_id IN (4, 6)) SELECT *, NTILE(3) OVER (PARTITION BY product_id ORDER BY days_since_last_restock, id) AS days_since_last_restock_bucket, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock DESC, id) AS event_seq, LAST_VALUE(quantity, TRUE) OVER (PARTITION BY product_id ORDER BY days_since_last_restock, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_quantity, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY quantity DESC, id) AS row_seq FROM filtered;
